        if(!in_array($origin['state'],['api_registered','api_query_observed'],true))throw new \DomainException('bb_api_address_requires_fresh_normal_query');$query=$this->rows("SELECT * FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='query' ORDER BY id DESC LIMIT 1 FOR UPDATE",[$originId])[0]??null;$data=$query?json_decode($query['result_json'],true,32,JSON_THROW_ON_ERROR):[];
        if(!$query||$query['status']!=='validated'||(int)$query['http_status']!==200||!preg_match('/^[a-f0-9]{64}$/D',$query['response_hash'])||$query['updated_at']<gmdate('Y-m-d H:i:s',time()-300)||$query['updated_at']>gmdate('Y-m-d H:i:s')||($data['codigoEstadoTituloCobranca']??null)!=='1'||($data['account_scope_confirmed']??null)!=='1'||!preg_match('/^[a-f0-9]{64}$/D',$data['account_evidence_hash']??''))throw new \DomainException('bb_api_address_requires_fresh_normal_query');
        if(!is_array($data['bank_address']??null)||!hash_equals(ApiAddress::addressHash($data['bank_address']),$data['bank_address_hash']??''))throw new \DomainException('bb_api_address_query_requires_review');if(hash_equals(ApiAddress::addressHash($intent),$data['bank_address_hash']))throw new \DomainException('bb_api_address_unchanged');
