        $data=json_decode($last['result_json'],true,32,JSON_THROW_ON_ERROR);$intent=ApiAddress::input($data['address_instruction']??[]);[$original,,$snapshot]=$this->loadOrigin($issuer,$origin);if(($data['address_contract']??null)!==ApiAddress::CONTRACT||!hash_equals(ApiAddress::fingerprint($original,$snapshot,$intent),$data['address_fingerprint']??''))throw new \DomainException('bb_api_address_corrupt');if(!is_array($result['bank_address']??null)||!hash_equals(ApiAddress::addressHash($result['bank_address']),ApiAddress::addressHash($intent))||!hash_equals(ApiAddress::addressHash($intent),$result['bank_address_hash']??'')||($result['account_scope_confirmed']??null)!=='1'||!preg_match('/^[a-f0-9]{64}$/D',$result['account_evidence_hash']??''))throw new \DomainException('bb_api_address_bank_divergence');$data['bank_state']='address_confirmed';$data['account_evidence_hash']=$result['account_evidence_hash'];$json=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);\IssuerStorage::query($this->db,"UPDATE {$this->prefix}bb_api_operations SET status='confirmed',result_json=?,updated_at=? WHERE id=?",[$json,gmdate('Y-m-d H:i:s'),$id]);$saved=$this->rows("SELECT status,result_json FROM {$this->prefix}bb_api_operations WHERE id=?",[$id])[0]??[];if(($saved['status']??null)!=='confirmed'||($saved['result_json']??null)!==$json)throw new \RuntimeException('issuer_bb_api_write_unconfirmed');
    }
}
